{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "SDI enable configuration",
      "Unit": "neorv32_sdi",
      "Information": "The enable setting controls whether the SDI engine and both receive and transmit FIFOs operate. The bus can write it and read it back.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because a bus write changes the stored enable setting at line 133; availability is at risk because it clears both FIFOs at lines 200 and 239 and controls serial operation at line 296.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker issuing a bus write can disable the interface, clear buffered data, and prevent normal SDI transfers.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        117,
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "SDI transmit data",
      "Unit": "neorv32_sdi",
      "Information": "The transmit byte supplied by the bus is serialized onto sdi_dat_o. The SDI transmit function depends on preserving and delivering this byte.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because the byte crosses the observable serial output at line 345; integrity is at risk because bus data is accepted into the transmit path at line 201; availability is at risk because the transmit FIFO can be cleared at line 200 and serialization only starts when chip select is active at line 307.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker can replace a bus-supplied transmit byte or clear the transmit path while an observer samples sdi_dat_o.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "SDI receive data",
      "Unit": "neorv32_sdi",
      "Information": "The serial byte received on sdi_dat_i is assembled and returned to the bus through the receive-data read path. The receive function depends on retaining the received byte until it is read.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because received data is exposed through bus_rsp_o.data at line 162; integrity is at risk because sdi_dat_i is sampled at line 270 and incorporated into the receive shift register at line 327; availability is at risk because the receive FIFO can be cleared at line 239 or popped by a bus read at line 240.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker can inject or corrupt serial input bits, or cause the receive FIFO to be cleared or consumed before the bus reads the byte.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "SDI chip-select transfer handshake",
      "Unit": "neorv32_sdi",
      "Information": "The chip-select state determines whether serial words are accepted or transmitted and its active state is reported by the bus status readback. SDI transfers depend on this link-level handshake.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Availability is at risk because the serial engine starts only when the synchronized chip select is active at line 307 and returns to an idle state when it becomes inactive at lines 315 and 324, allowing the transfer to be blocked.",
      "Objectives At Risk": [
        "A"
      ],
      "Attack": "An attacker can hold or manipulate chip select so that the interface does not start, continue, or complete an SDI transfer.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        269
      ],
      "Held Lines": [],
      "Exit Lines": [
        160
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "SDI interrupt notification",
      "Unit": "neorv32_sdi",
      "Information": "irq_o reports configured receive and transmit FIFO conditions to the integrating processor. The processor may depend on this notification to service buffered SDI data.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because irq_o is formed from writable interrupt enables and FIFO status at lines 249 through 254; availability is at risk because the enable and interrupt masks can suppress the notification through the same logic.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can alter the interrupt-enable settings or FIFO conditions to suppress a required interrupt or generate a false one.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        247,
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Clock and reset infrastructure",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The clock and reset rule excludes clk_i, rstn_i, and the serial clock sdi_clk_i from conceptual assets; their uses appear at lines 23, 24, 28, 115, 123, 184, 185, 219, 220, 268, and 269."
    },
    {
      "Candidate Name": "FIFO depth build-time setting",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO only fixes FIFO construction and depth through the generic at lines 20 and 176 and cannot be changed or withheld at run time."
    },
    {
      "Candidate Name": "Interrupt-enable settings",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The interrupt-enable fields are bus-written settings whose only functional use is tuning the irq_o interrupt output, so the Port options rule excludes them as pieces of their own; their uses are shown at lines 135 through 139 and 249 through 254."
    },
    {
      "Candidate Name": "FIFO occupancy and buffer status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The FIFO availability, half-full, free, and bus-read status bits only report whether buffered data can move or was lost, so the Buffer and engine status bits rule excludes them as independent information; the readback assignments are at lines 153 through 158."
    },
    {
      "Candidate Name": "Serial engine sequencing and pacing state",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "serial.state and serial.cnt only order and pace the serial transfer, so Sequencing state excludes them as concepts of their own; their assignments and tests are at lines 286 through 340."
    },
    {
      "Candidate Name": "Serial start and completion pulses",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "serial.start and serial.done only pace FIFO transfers and mark the end of a serial step, so the Pacing pulses rule excludes them; they are assigned at lines 292, 308, and 329."
    },
    {
      "Candidate Name": "Bus access commands and handshake copies",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The bus request strobe, direction, and address fields are access command fields, while the acknowledge and constant error response are handshake copies, so they are not independent concepts; the relevant logic is at lines 125, 130 through 142, and 202 and 240."
    },
    {
      "Candidate Name": "Synchronizer staging",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The synchronizer registers and derived wires only resample or carry serial clock, chip-select, and data inputs, so Working values and the synchronizer exclusions prevent them from being concepts of their own; they are assigned at lines 264 through 276."
    }
  ],
  "Notes": []
}
